#pragma once
#include "UnifiedWorkflow.h"
#include <QTextBrowser>
#include <QTextDocument>
#include <QPushButton>
#include <QVBoxLayout>
#include <QLineEdit>
#include <QLabel>
#include <QUrl>

inline QWidget* unifiedWorkflowHelp() {
    using unified_workflow::text;
    auto host=new QWidget;host->setObjectName("workflowHelp");auto layout=new QVBoxLayout(host);
    auto search=new QLineEdit;search->setObjectName("workflowHelpSearch");search->setPlaceholderText(text("Kılavuzda ara · Enter ile sonraki sonuç","Search guide · Enter for next match"));layout->addWidget(search);
    auto browser=new QTextBrowser;browser->setObjectName("workflowHelpText");browser->setOpenExternalLinks(true);layout->addWidget(browser,1);
    QObject::connect(search,&QLineEdit::returnPressed,browser,[=]{if(!browser->find(search->text())){browser->moveCursor(QTextCursor::Start);browser->find(search->text());}});
    QString html="<html><head><style>body {line-height:1.5;} h2 {margin-top:30px;} td {padding:8px;} .note {background:#edf3f7;color:#172431;padding:12px;}</style></head><body>";
    html+="<h1>"+text("Resimden aranabilir PDF’ye","From images to searchable PDF")+"</h1><p>"+text(
        "Sıra: Girdi → Yön → Bölme → Geometri → AI geometri → İçerik → AI içerik → Kenarlar → Çıktı → Temizlik → PDF → OCR → Önbellek temizliği. AI ve temizlik isteğe bağlıdır. Her aşama kendi satırındaki ▶ ile çalışır. Ayarlar ve yardım işlem yapmaz.",
        "Order: Input → Orientation → Split → Geometry → AI geometry → Content → AI content → Margins → Output → Cleanup → PDF → OCR → Cache cleanup. AI and cleanup are optional. Each operation has its own ▶. Settings and Help do not process pages.")+"</p>";
    html+="<p>";
    for(auto const& step:unified_workflow::steps())html+="<a href='#"+step.id+"'>"+step.title.toHtmlEscaped()+"</a> &nbsp; ";
    html+="</p>";
    int imageNumber=0;
    auto button=[&](QString title,QString explanation){
        QPushButton sample(title);sample.setFont(host->font());sample.ensurePolished();sample.resize(sample.sizeHint());
        QImage pic=sample.grab().toImage();auto url=QUrl("help-button:"+QString::number(++imageNumber));
        browser->document()->addResource(QTextDocument::ImageResource,url,pic);
        html+="<table><tr><td><img src='"+url.toString()+"' width='"+QString::number(pic.width()/pic.devicePixelRatio())+"' height='"+QString::number(pic.height()/pic.devicePixelRatio())+"'></td><td><b>"+title.toHtmlEscaped()+"</b><br>"+explanation.toHtmlEscaped()+"</td></tr></table>";
    };
    auto section=[&](QString id,QString body){auto step=unified_workflow::steps().at(unified_workflow::row(id));html+="<h2 id='"+id+"'><a name='"+id+"'></a>"+step.title+"</h2><p>"+body+"</p>";};
    section("input",text("Kaynak dosyalar korunur. Bir kitap için resimleri veya tek klasörü açın. Üst klasör, alt klasörleri ayrı kitaplar olarak kuyruğa ekler. PDF önce resimlere dönüştürülür; sonra aynı 1–11 akışı uygulanır. Metinli PDF'yi yeniden resimleştirmek mevcut aranabilir metni kaldırır; görünümü ve metni korumak için PDF araçlarındaki Akıllı PDF seçeneğini kullanın.","Sources are preserved. Open images or one folder for one book. A parent folder adds subfolders as separate queue books. PDF import first creates images, then uses stages 1–11. Rasterizing a digital PDF removes its existing searchable text; use Smart PDF in PDF tools to preserve appearance and text."));
    button(text("Resim seç","Select images"),text("Bir veya birden fazla JPG, PNG, TIFF veya BMP seçer; dosyalar doğal ad sırasıyla açılır. Çok sayfalı TIFF desteklenir.","Select one or more JPG, PNG, TIFF or BMP files in natural filename order. Multipage TIFF is supported."));
    button(text("Klasör seç","Select folder"),text("Klasörün doğrudan içindeki resimleri tek düzenleme projesi olarak açar.","Open the images directly inside a folder as one editable project."));
    button(text("Üst klasör seç","Select parent folder"),text("Resim içeren alt klasörleri ayrı kitaplar olarak ekler. İşler bölümünde kitap seçip hazırlayın; ardından düzenleyin.","Add image subfolders as separate books. Select and prepare a book in Jobs, then edit it."));
    button(text("PDF seç ve düzenle","Select and edit PDF"),text("Sayfa aralığı, gömülü resim çıkarma veya sayfa işleme seçeneklerini açar. İçe aktar tamamlanınca resimler düzenlemeye hazırdır.","Open page range, embedded-image extraction or page rendering options. Imported images become available for editing."));
    button(text("Çıktı klasörünü seç","Choose output folder"),text("Yeni PDF sürümlerinin kaydedileceği yeri seçer. Açılmış projenin TIFF çıktı klasörü proje ayarı olarak kalır; Girdi ekranı ikisini de gösterir.","Choose where new PDF versions are saved. An open project's TIFF folder remains a project setting; Input displays both locations."));
    section("orientation",text("Sayfanın üst yönünü belirleyin. Bu adım 90° döndürür; küçük eğiklik 3. aşamadadır.","Set the upright direction. This stage rotates by 90°; small skew is handled in stage 3."));
    button("↶ / ↷",text("Geçerli görüntüyü sola/sağa döndürür. Uygula… kapsam diyaloğu aynı dönüşü seçilen sayfalara kopyalar.","Rotate the current image left/right. Apply… copies the rotation to the chosen page scope."));
    section("split",text("Tek sayfa, çift sayfa veya otomatik algılama seçin. Bölme çizgisini sürükleyerek iki sayfanın sınırını düzeltin. Sayfa silme ile içerik kırpma farklıdır.","Choose single page, spread or automatic detection. Drag the split line to correct the boundary. Removing a page differs from cropping its content."));
    button(text("Otomatik / Elle","Auto / Manual"),text("Otomatik seçim görüntüden hesaplanır. Elle seçim kaydedilir ve toplu işlem sırasında korunur.","Automatic selection is estimated from the image. Manual selection is saved and retained during batch processing."));
    section("geometry",text("Döndürme/eğiklik, perspektif ve eğri çizgiler seçenekleri normal geometri araçlarıdır. Kontrol noktalarını sürükleyerek metin satırlarını düzleştirin. Bu aşamanın ▶ düğmesi AI analizi başlatmaz.","Rotation/skew, perspective and curved lines are standard geometry tools. Drag control points to straighten text lines. This stage's ▶ does not start AI analysis."));
    button("▶",text("Normal aşamalarda kitabın tamamını bu aşamaya kadar mevcut Auto/Manual ayarlarıyla işler. Görüntü üzerinde tek sayfa düzenlemek için toplu ▶ zorunlu değildir.","At standard stages, process the whole book through that stage using existing Auto/Manual settings. You need not run the batch ▶ to edit a single page."));
    section("ai_geometry",text("AI geometri, normal geometriden sonra ayrı bir öneri adımıdır. CPU'da ağır olabilir; sonuç daha iyi değilse kullanmayın. Aynı sayfa ayarlarını kullanır; bu ekrandaki normal araçlarla da elle düzeltilebilir. AI çalışması önceki aşamaların hazırlanmasını gerektirir.","AI geometry is a separate proposal stage after standard geometry. It can be expensive on CPU; skip a proposal if it is not better. It shares page settings with the standard stage, whose manual tools remain available here. Prior stages must be prepared first."));
    button(text("▶ Hazırla","▶ Prepare"),text("Seçilen kapsamı inceler ve aday üretir; henüz uygulamaz. Aşama satırındaki ▶ de aynı analizi başlatır. İlk model yüklemesi sonraki sayfalardan uzun sürebilir.","Analyze the chosen scope and create candidates without applying them. The stage-row ▶ starts the same analysis. The first model load can take longer than subsequent pages."));
    button(text("Öneriyi göster","Show suggestion"),text("Önerinin karşılaştırmasını ana görüntüde açar. Tekrar basmak düzenlemeye döndürür. Tekerlek yakınlaştırır; sürüklemek görüntüyü kaydırır.","Show the proposal comparison in the main view. Press again to return to editing. The wheel zooms; dragging pans."));
    button(text("▶ Uygula / ▶ Toplu","▶ Apply / ▶ Batch"),text("Hazır adayı seçilen kapsamın kayıtlı geometri/içerik ayarına uygular. Toplu işlem elle düzenlenmiş sayfaları korur. Uygulamak, yalnız önizleme açmaktan farklıdır.","Apply a prepared candidate to the saved geometry/content settings for the selected scope. Batch application protects manual edits. Applying differs from merely showing a preview."));
    button(text("Yalnız bu sayfa / Seçili sayfalar / Kitabın tamamı","This page / Selected pages / Whole book"),text("Hazırla ve Uygula kapsamıdır. Küçük resimlerde Ctrl ile tek tek, Shift ile aralık seçebilirsiniz. Toplu işlem her sayfanın kendi önerisini kullanır.","The scope for Analyze and Apply. Use Ctrl for individual thumbnails and Shift for a range. Batch application uses each page's own proposal."));
    button(text("Elle ayarım da değişebilir","Allow replacing my manual setting"),text("Yalnız bu sayfada elle yaptığınız ayarın AI önerisiyle değiştirilmesine izin verir. Toplu işlem için genel bir izin değildir.","Allow the AI proposal to replace a manual setting on this page only. This is not a blanket permission for batch edits."));
    button(text("Son uygulamayı geri al","Undo last application"),text("Son AI uygulama grubunu geri alır. Sonradan elle değişen ayarlar korunur; eski, artık uyuşmayan öneriler yeniden hazırlanmalıdır.","Undo the last AI application group. Later manual edits are protected; outdated proposals must be regenerated."));
    button(text("Durdur","Stop"),text("Devam eden analizi durdurur. Tamamlanmış ve kaydedilmiş ayarları geri almaz.","Stop the current analysis. This does not undo completed, saved settings."));
    button(text("İşlemci ve ayrıntılar","Device and details"),text("CPU/GPU seçimi ve ayrıntılı aday karşılaştırmasını açar. GPU yalnız uygun çalışma ortamı kurulu ve cihaz testi başarılıysa kullanılır.","Show CPU/GPU selection and detailed candidate comparison. GPU requires the corresponding runtime and a successful device test."));
    section("content",text("Korunacak içerik kutusunu kenarlarından sürükleyin. Metin, resim, dipnot ve sayfa numaralarını kontrol edin. Bu kutu AI içerik ekranıyla ortaktır. AI yanlış seçtiyse bu ekranda veya AI ekranında elle düzeltin; Çıktı bu kayıtlı seçimi kullanır.","Drag the edges of the content box. Check text, pictures, footnotes and page numbers. This box is shared with AI content selection. Correct a mistaken AI selection manually here or on the AI screen; Output uses that saved selection."));
    section("ai_content",text("Paddle düzen modeli metin, başlık, tablo ve resim gibi bölgeler için etiket, kutu ve güven puanı önerebilir. Her alanın eksiksiz etiketlenmesi garanti değildir. İçerik seçimi bu bölgelerden korunacak alanı önerir. Sıradan Paddle OCR seçimi tek başına bütün düzen etiketlerini üretmez; OCR ile düzen analizi ayrı işlemlerdir.","A Paddle layout model can propose labels, boxes and confidence scores for text, headings, tables and pictures. Complete labeling is not guaranteed. Content selection derives a retained area from these proposals. Selecting ordinary Paddle OCR alone does not produce every layout label; OCR and layout analysis are separate operations."));
    section("margins",text("Kenar payları ve hizalama içerik seçiminin çevresindeki alanı belirler. Sayfaları aynı boyuta eşitleme, PDF'deki yazı büyüklüğünü eşitlemeyle aynı değildir. İçeriği değiştirdiğinizde bu aşama yeni kutuyu kullanır.","Margins and alignment determine the area around selected content. Matching page sizes differs from matching text size in PDF. This stage uses the new box after content changes."));
    section("output",text("DPI/ölçek, siyah-beyaz veya renkli görünüm, eşikleme, nokta temizleme, resim bölgeleri ve dolgu bölgeleri bu aşamadadır. ▶ tüm kitabın güncel görüntüsünü üretir. Kaynak fotoğraflar değiştirilmez. Sayfa düzenlemeleri çıktı önizlemesine yansır; daha önce kaydedilmiş PDF'nin yenilenmesi ayrıca gerekir.","This stage controls DPI/scale, monochrome or color appearance, thresholding, despeckling, picture zones and fill zones. ▶ renders current images for the entire book. Source photos are preserved. Page edits affect the output preview; an already saved PDF must be regenerated."));
    button(text("Dolgu bölgeleri","Fill zones"),text("Bir lekenin çevresine çokgen çizin; başlangıç noktasına dönerek kapatın ve dolgu rengini seçin. Metin üzerine çizmek o metni de kapatır. Parmak altındaki görünmeyen harfler yeniden oluşturulmaz.","Draw a polygon around a stain, close it at the starting point and choose a fill color. Drawing over text hides it too. Letters obscured by a finger are not reconstructed."));
    section("cleanup",text("Çıktıdan sonra, PDF'den önce çalışır. Kenardaki kopuk leke ve parmak benzeri izleri önerir. Harf benzeri parçalar, sayfa numaraları ve belirsiz tablo/resim alanları korunur. Bu işlem OCR yapmaz. Öneriyi önizleyin; yalnız uygunysa uygulayın. Seyrek/resimli sayfalarda otomatik silme yapılmayabilir.","Runs after Output and before PDF. Proposes detached edge stains and finger-like marks. Glyph-like components, page numbers and uncertain table/picture regions are retained. This stage does not run OCR. Preview and apply only if suitable. Sparse or illustrated pages may receive no automatic cleanup."));
    button(text("▶ Temizliği hazırla","▶ Prepare cleanup"),text("Kapsamdaki güncel çıktı görüntülerini inceler. Önce/sonra ve maske dosyalarını hazırlar. Henüz PDF'ye uygulanmaz.","Analyze current output images in the chosen scope. Prepare before/after images and masks. Nothing is applied to PDF yet."));
    button(text("Önce / sonra","Before / after"),text("Seçili sayfanın kaynak görüntüsünü ve temizlenmiş önerisini açar. Her sayfayı listeden ayrı inceleyin.","Open the original output and cleaned proposal for the selected page. Review each page separately in the list."));
    button(text("Temizliği uygula","Apply cleanup"),text("Gözden geçirdiğiniz öneriyi sonraki PDF'ye dahil eder. Orijinal TIFF korunur. Çıktı pikselleri veya ayarlar değişirse eski maske reddedilir; yeniden hazırlayın.","Include the reviewed proposal in the next PDF. Original TIFFs are preserved. If output pixels or settings change, the old mask is rejected; prepare it again."));
    button(text("Temizliği geri al","Undo cleanup"),text("Bu önerinin PDF'de kullanılmasını kaldırır. Önceki PDF dosyası silinmez; yeni PDF oluşturun.","Stop using this proposal in PDF. Previous PDFs are not deleted; generate a new PDF."));
    section("pdf",text("▶ PDF oluştur, önce güncel Çıktı görüntülerini hazırlar, sonra yalnız bu açık kitap için görüntü PDF'si üretir. OCR daha sonra yapılır. Sayfa numaraları, resimler ve açıklamalar taşmasın diye sığdırma sınırı uygulanır. Her oluşturma ayrı sürüm kaydeder.","▶ Create PDF first refreshes Output, then creates an image PDF for this open book only. OCR follows later. Fitting limits protect page numbers, pictures and captions from overflowing. Each run saves a new version."));
    button(text("A4 · sığdır / A4 · doldur / Yazı boyutunu eşitle / Yerel","A4 · fit / A4 · fill / Match text size / Native"),text("Sığdır ortak piksel ölçeği kullanır. Doldur her sayfayı mevcut boşluğa büyütür. Yazı eşitle harf yüksekliğini görüntüden ölçer; OCR çalıştırmaz. Güven düşükse kitap ortancası kullanılır. Geniş sayfa sığmazsa küçültülür; tam eşitlik garanti değildir. Yerel boyut 300 DPI kabulüyle görüntü boyutundan hesaplanır.","Fit uses a common pixel scale. Fill enlarges each page to available space. Match text size measures glyph height in the image without OCR; low-confidence pages use the book median. Oversized pages shrink to fit, so exact equality is not guaranteed. Native size is derived from image size at an assumed 300 DPI."));
    button(text("İçeriğe sığdır / Kenar payı / Hedef yazı yüksekliği","Fit content / Margin / Target text height"),text("İçeriğe sığdır boş tuvali dışarıda bırakır ama tüm görünür işaretleri korur. Kenar payı mm cinsindedir. Hedef 0 ise otomatik ortak yükseklik seçilir; elle değer mm cinsindedir. Belirsiz sayfaların yerleşim raporunu kontrol edin.","Fit content excludes blank canvas while retaining visible marks. Margins are in mm. Target 0 selects an automatic common height; a manual target is in mm. Check layout warnings on uncertain pages."));
    section("ocr",text("Son PDF'nin görüntüsünü değiştirmeden görünmez aranabilir metin katmanı eklenir. Tesseract Fast düşük işlem gücünde başlangıç seçeneğidir. Best daha yavaştır ve her sayfada daha doğru olacağı garanti değildir. Paddle uygun cihaz/modelle kullanılabilir. Dil, çözünürlük, eğiklik, eski yazı, tablo ve baskı kalitesi sonucu etkiler.","Adds an invisible searchable text layer without changing the final PDF appearance. Tesseract Fast is a starting option for low-powered devices. Best is slower and is not guaranteed to be better on every page. Paddle requires a suitable device/model. Language, resolution, skew, historical print, tables and print quality affect results."));
    button(text("▶ OCR ekle","▶ Add OCR"),text("Önce 10. aşamada oluşturulan güncel PDF'yi kullanır. Geometri, içerik veya PDF ayarları sonradan değiştiyse PDF'yi yenilemenizi ister. Yeni aranabilir PDF kaydeder; görüntü PDF'si korunur.","Use the current PDF created at stage 10. If geometry, content or PDF settings changed, regenerate PDF first. Save a new searchable PDF and preserve the image PDF."));
    html+="<p class='note'>"+text("Tesseract için bu kitaplarda ölçülmüş sabit bir doğruluk yüzdesi yok. Model güven puanı doğruluk oranı değildir. Gerçek doğruluk, insanın doğruladığı referans metinle CER/WER karşılaştırmasıyla ölçülür. 0 insan doğrulamalı sayfa varsa doğruluk ölçüldü denemez. OCR hatalarını özellikle rakam, dipnot ve özel adlarda gözle kontrol edin.","There is no measured universal Tesseract accuracy percentage for these books. Model confidence is not accuracy. Measure accuracy against human-verified reference text using CER/WER. With zero human-verified pages, accuracy has not been measured. Check numbers, footnotes and proper names carefully.")+"</p>";
    section("storage",text("Bu projenin sahipliği kayıtlı dosyalarının gerçek boyutu kategori bazında gösterilir. Sakla kutuları; kaynak kopyaları, ara TIFF, OCR metin önbelleği, önizlemeler ve geçici PDF’ler içindir. Modeller ve başka kitapların dosyaları bu temizliğe dahil değildir. Nihai PDF’ler ve sayfa güncelleme kayıtları korunur. Açık veya önceden kaydedilmiş projede gerekli girdi resimleri ve onaylı düzeltmeler silinmez.","Actual sizes of this project's registered files are shown by category. Keep boxes cover input copies, intermediate TIFFs, OCR text cache, previews and temporary PDFs. Models and other books are outside this cleanup. Final PDFs and page-update records are protected. Required inputs and approved corrections of open or previously saved projects are retained."));
    button(text("Boyutları yenile","Refresh sizes"),text("Dosyaları tekrar sayar; toplam, seçime göre silinebilir ve korunacak alanı günceller. İşletim sistemi sıkıştırması nedeniyle diskte kaplanan alan farklı olabilir.","Recount files and update total, removable and retained bytes. Actual allocated disk space may differ due to filesystem compression."));
    button(text("Seçime göre temizle","Clean selected categories"),text("Sakla işareti kapalı kategorileri şimdi temizler. Çalışan işlem varken temizlemez. Görünür TIFF’leri silmeden önce son PDF’nin bütünlüğünü doğrular. Kaynak kitap, eski PDF sürümleri ve kayıtlı düzeltmeler korunur. Bir önizleme silinirse tekrar hazırlanır; OCR önbelleği silinse de son PDF’nin aranabilir metni kalır.","Clean unchecked categories now. Cleaning is blocked during active processing. The final PDF is verified before visible TIFFs can be removed. Source books, previous PDFs and saved corrections remain. Deleted previews must be regenerated; deleting OCR cache keeps searchable text already in the final PDF."));
    button(text("Temizlik zamanı","Cleanup timing"),text("Yalnız elle, başarılı PDF sonrasında, başarılı OCR sonrasında veya proje kapanırken seçenekleri vardır. OCR yapılacaksa OCR sonrası uygundur. Başarısız işlem otomatik son temizliği başlatmaz. Ayarlar projede ve sonraki projelerin varsayılanlarında saklanır.","Choose manual, after successful PDF export, after successful OCR or on project close. After OCR is suitable when recognition is planned. Failed processing does not trigger final cleanup. Policy is saved for this project and as defaults for new projects."));
    button(text("Kaydetmeden kapatılan yeni projenin geçici dosyalarını sil","Delete temporary files when a new project closes without saving"),text("Açıksa yeni projede Kaydetme seçimi, saklama kutularından önce gelir: geçici girdi kopyaları, OCR önbelleği ve analiz dosyaları silinir. Görünür Çıktı TIFF’leri ve nihai PDF’ler kalır. Kaydet veya İptal seçimi bunu tetiklemez; önceden kaydedilmiş proje bağımlılıkları korunur.","When enabled, Discard on a new project overrides Keep boxes: temporary inputs, OCR cache and analysis files are removed. Visible Output TIFFs and final PDFs remain. Save or Cancel does not trigger this rule; previously saved project dependencies remain protected."));
    section("settings",text("Bütün araç ayarları tek merkezde tutulur: PDF yerleşimi/görünümü, OCR motoru/dilleri, işlemci sınırı, GPU, kayıt klasörleri, başlangıç profili ve kitap kuyruğu. Bu aşamadaki değiştirmeler ilgili PDF/Çıktı kontrollerine de yansır. Yerel uygulama ayarları ayrıca aynı ekrandan açılır. Dil menüsündeki seçim yeniden başlatınca uygulanır; kılavuz ve aşamalar aynı dilde açılır.","All tool settings share one source: PDF layout/appearance, OCR engine/languages, CPU limits, GPU, folders, startup profile and queue. Changes here synchronize with the related PDF/Output controls. Native application settings are also accessible here. Language-menu changes take effect after restarting; stages and guide use the same language."));
    button(text("Başlangıç ayarları","Startup settings"),text("Hız profili, OCR zamanı, çıktı ve geçici klasörleri tekrar seçin. CPU Hızlı: düşük ölçek, ağır AI kapalı, OCR en sonda. CPU kalite ve AI geometri daha uzun sürebilir. Büyük DPI ve çok sayfa bellek/disk tüketimini artırır.","Choose speed profile, OCR timing, output and temporary folders again. CPU Fast uses lower scale, disables heavy AI and puts OCR last. CPU Quality and AI geometry can take longer. High DPI and large books increase memory/disk use."));
    html+="<h2>"+text("Değişiklikten sonra ne olur?","What happens after an edit?")+"</h2><p>"+text("Normal ve AI geometri aynı ayarları; normal ve AI içerik aynı kutuyu düzenler. Bir sayfadaki düzeltme yalnız o sayfanın sonraki işlemlerini yeniler. PDF ▶, değişen Çıktı sayfasını yeniden üretip diğer PDF sayfalarını mevcut OCR metniyle korur. PDF önceden OCR’lıysa yalnız değişen sayfaya otomatik OCR eklenir. Eski temizlik maskesi o sayfaya uymuyorsa uygulanmaz; yeniden inceleme uyarısı gösterilir. Ortak kâğıt boyutu gibi kitap genelindeki ayarlar tüm etkilenen sayfaları yeniler. Bir çift fotoğrafın yön/bölme ayarı iki alt sayfayı da etkileyebilir. Ara TIFF’ler temizlense bile değişmeyen sayfalar doğrulanmış PDF’den alınır. Her PDF ayrı sürümdür.","Standard and AI geometry share settings; standard and AI content share the content box. A page edit refreshes only that page downstream. PDF ▶ renders its updated Output and preserves other PDF pages with their existing OCR. If the previous PDF had OCR, only changed pages are recognized automatically. A stale cleanup mask is skipped on that page and a review warning is shown. Book-wide changes such as paper size update all affected pages. Orientation/splitting of one spread may affect both halves. After TIFF cleanup, unchanged pages still come from the verified PDF. Each PDF is a separate version.")+"</p>";
    html+="<h2>"+text("Süre ve kısayollar","Timing and shortcuts")+"</h2><p>"+text("Satırdaki saniye gerçek geçen süredir, tahmin değildir. İşlemci yükü, ilk model açılışı ve sayfa çözünürlüğü süreyi değiştirir. Ctrl+S proje kaydeder; PDF üretmez. Ctrl+0 yalnız görüntüyü ekrana sığdırır; PDF boyutunu değiştirmez. Ctrl+Alt+A AI hazırla; Ctrl+Alt+P öneri önizle; Ctrl+Alt+Enter uygula; Ctrl+Alt+Backspace geri al. Sağdaki sayfa küçük resimlerinden sayfa seçilir. Toplu işlem sırasında Duraklat bekletir, Devam sürdürür, Durdur kalan işi iptal eder.","Seconds in each row show elapsed time, not an estimate. CPU load, initial model startup and page resolution affect duration. Ctrl+S saves the project, not a PDF. Ctrl+0 fits the view only. Ctrl+Alt+A analyzes AI; Ctrl+Alt+P previews; Ctrl+Alt+Enter applies; Ctrl+Alt+Backspace undoes. Choose pages in the thumbnail panel. During native batch processing, Pause waits, Resume continues, and Stop cancels remaining work.")+"</p>";
    html+="<h2>"+text("Kaynaklar","Sources")+"</h2><p><a href='https://tesseract-ocr.github.io/tessdoc/ImproveQuality.html'>Tesseract: Improving quality</a><br><a href='https://tesseract-ocr.github.io/tessdoc/Data-Files-in-tessdata_fast.html'>Tesseract Fast models</a><br><a href='https://github.com/PaddlePaddle/PaddleOCR/blob/main/docs/version3.x/module_usage/layout_detection.en.md'>PaddleOCR: Layout detection</a><br><a href='https://github.com/PaddlePaddle/PaddleOCR/blob/main/docs/version3.x/pipeline_usage/PP-StructureV3.en.md'>PP-StructureV3</a></p>";
    html+="<a name='help'></a></body></html>";browser->setHtml(html);browser->moveCursor(QTextCursor::Start);return host;
}
